W=Path('/workspace/work/musicxml-compound-rest');R=Path('/workspace/audiveris-native');D=W/'fresh-main.git';G=W/'fresh-source.git';stage='sol-function-parity-ledger-20261005';sha=lambda b:hashlib.sha256(b).hexdigest()
