p=subprocess.run(['git','--git-dir='+str(D),'fetch','--depth','1','origin','refs/heads/main'],capture_output=True);assert p.returncode==0,'existing connection fetch failed; no bypass';run(D,'update-ref','HEAD',run(D,'rev-parse','FETCH_HEAD').decode().strip());head=run(D,'rev-parse','HEAD').decode().strip();assert head==subprocess.check_output(['git','-C',str(R),'rev-parse','HEAD'],text=True).strip();tree=run(D,'rev-parse','HEAD^{tree}').decode().strip();assert tree==subprocess.check_output(['git','-C',str(R),'rev-parse','HEAD^{tree}'],text=True).strip()
